/**
 * Text measurement for card layout.
 *
 * The previous generator picked type size from a two-value ladder keyed on
 * `headline.length > 46`, which is why the 1200x630 founder card overflowed its
 * body box by ~20px: character count is not width. This measures the actual
 * advance widths of the actual fonts, so the fit loop in layout.ts can make a
 * real decision.
 *
 * Widths come from the committed table in font-metrics.ts (generated by
 * scripts/extract-font-metrics.mjs), so this works identically in the render
 * script and in the edge route, with no dependency and no runtime font parsing.
 */

import { SERIF_METRICS, MONO_METRICS, type FontMetrics } from './font-metrics';

export { SERIF_METRICS, MONO_METRICS };
export type { FontMetrics };

/**
 * Satori shapes text with kerning and ligatures; this table does not. The
 * difference is under a percent for these faces, but it is signed the wrong way
 * — a slightly narrow estimate means a line satori decides to wrap. Treat the
 * available width as marginally smaller so every estimate errs toward
 * wrapping early rather than overflowing.
 */
const SAFETY = 0.985;

export interface TextStyle {
  metrics: FontMetrics;
  fontSize: number;
  /** In em, matching CSS `letter-spacing: 0.28em`. */
  letterSpacing?: number;
  lineHeight: number;
}

/** Width of a single run of text in pixels, with no wrapping. */
export function measureLine(text: string, style: TextStyle): number {
  const { metrics, fontSize, letterSpacing = 0 } = style;
  let em = 0;
  for (const ch of text) em += metrics.widths[ch] ?? metrics.fallback;
  // Tracking applies between glyphs, and CSS also adds it after the last one.
  return (em + letterSpacing * [...text].length) * fontSize;
}

/**
 * Greedy line breaking, matching how satori breaks on whitespace.
 * A single word longer than maxWidth gets its own line rather than being split,
 * which is also what satori does with `overflow-wrap: normal`.
 */
export function wrapText(text: string, style: TextStyle, maxWidth: number): string[] {
  const limit = maxWidth * SAFETY;
  const words = text.split(/\s+/).filter(Boolean);
  if (words.length === 0) return [];

  const lines: string[] = [];
  let current = words[0];

  for (let i = 1; i < words.length; i++) {
    const candidate = `${current} ${words[i]}`;
    if (measureLine(candidate, style) <= limit) {
      current = candidate;
    } else {
      lines.push(current);
      current = words[i];
    }
  }
  lines.push(current);
  return lines;
}

/** Rendered height of a wrapped block. */
export function measureBlock(text: string, style: TextStyle, maxWidth: number): {
  lines: string[];
  height: number;
} {
  const lines = wrapText(text, style, maxWidth);
  return { lines, height: lines.length * style.fontSize * style.lineHeight };
}
